python3 - <<'EOF'
import os,re,collections
decls=collections.defaultdict(list)  # name -> list of (file,line,recv)
gofiles=[]
for root,dirs,files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('node_modules','.git','gen')]
    for f in files:
        if f.endswith('.go'):
            gofiles.append(os.path.join(root,f))
pat=re.compile(r'^func\s+(?:\(([^)]*)\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\s*[\(\[]')
for p in gofiles:
    if not p.startswith('./internal/'): continue
    for i,line in enumerate(open(p,encoding='utf8',errors='ignore'),1):
        m=pat.match(line)
        if m: decls[m.group(2)].append((p,i,m.group(1) or ''))
# count call sites
callcount=collections.Counter()
callfiles=collections.defaultdict(set)
text={}
for p in gofiles:
    text[p]=open(p,encoding='utf8',errors='ignore').read().split('\n')
for name in decls:
    cp=re.compile(r'(?<![A-Za-z0-9_.])'+name+r'\s*\(|\.'+name+r'\s*\(')
    n=0
    for p,lines in text.items():
        for i,l in enumerate(lines,1):
            if l.startswith('func '): continue
            if '_test.go' in p: continue
            for _ in cp.finditer(l):
                n+=1
                callfiles[name].add(p)
    callcount[name]=n
for name,c in callcount.most_common(30):
    print(c, name, decls[name][:3], len(callfiles[name]))
EOF

perl -e '
use File::Find;
my @files;
find(sub { push @files, $File::Find::name if /\.go$/ && $File::Find::name !~ m{node_modules|/proto/gen/}; }, ".");
my %decl;
for my $f (@files) {
  next unless $f =~ m{^\./internal/};
  open my $fh, "<", $f or next; my $ln=0;
  while (<$fh>) { $ln++;
    if (/^func\s+(?:\(([^)]*)\)\s*)?([A-Za-z_]\w*)\s*[\(\[]/) { push @{$decl{$2}}, "$f:$ln"; }
  }
}
my %content;
for my $f (@files) { open my $fh,"<",$f or next; local $/; $content{$f}=<$fh>; }
my @res;
for my $name (keys %decl) {
  my $n=0; my %fs;
  for my $f (@files) {
    next if $f =~ /_test\.go$/;
    for my $line (split /\n/, $content{$f}) {
      next if $line =~ /^func /;
      my $c=0;
      $c++ while $line =~ /(?<![\w.])\Q$name\E\s*\(/g;
      $c++ while $line =~ /\.\Q$name\E\s*\(/g;
      if ($c) { $n+=$c; $fs{$f}=1; }
    }
  }
  push @res, [$n, $name, scalar(keys %fs), join(",", @{$decl{$name}}[0..($#{$decl{$name}}>2?2:$#{$decl{$name}})])];
}
for my $r (sort { $b->[0] <=> $a->[0] } @res[0..$#res]) { printf("%4d  %-30s files=%d  %s\n", @$r); }
' | head -30

perl -e '
use File::Find;
my @files;
find(sub { push @files, $File::Find::name if /\.go$/ && $File::Find::name !~ m{node_modules|/proto/gen/}; }, ".");
my %content; for my $f (@files) { open my $fh,"<",$f or next; local $/; $content{$f}=<$fh>; }
# collect package-level funcs per internal package dir
my %funcs; # "pkgdir|name" => decl loc
my %recvmeth; # name => decl loc (methods)
for my $f (@files) {
  next unless $f =~ m{^\./internal/};
  my $dir=$f; $dir =~ s{/[^/]+$}{};
  open my $fh,"<",$f or next; my $ln=0;
  while(<$fh>){ $ln++;
    if(/^func\s+([A-Za-z_]\w*)\s*[\(\[]/){ $funcs{"$dir|$1"}="$f:$ln"; }
    elsif(/^func\s+\(([^)]*)\)\s*([A-Za-z_]\w*)\s*[\(\[]/){ $recvmeth{$2}.="$f:$ln "; }
  }
}
my @res;
for my $k (keys %funcs) {
  my ($dir,$name)=split /\|/,$k;
  my $pkg=$dir; $pkg =~ s{.*/}{};
  my $n=0; my %fs;
  for my $f (@files) {
    next if $f =~ /_test\.go$/;
    my $own = ($f =~ m{^\Q$dir\E/[^/]+$});
    for my $line (split /\n/, $content{$f}) {
      next if $line =~ /^func /;
      my $c=0;
      if($own){ $c++ while $line =~ /(?<![\w.])\Q$name\E\s*\(/g; }
      else { $c++ while $line =~ /(?<![\w])\Q$pkg\E\.\Q$name\E\s*\(/g; }
      if($c){$n+=$c;$fs{$f}=1;}
    }
  }
  push @res,[$n,"$pkg.$name",scalar(keys %fs),$funcs{$k}];
}
for my $r (sort { $b->[0] <=> $a->[0] } @res) { printf("%4d  %-34s files=%d  %s\n", @$r) if $r->[0]>3; }
'

